import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter="\t",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = list(reader)

    def is_header(record: list[str]) -> bool:
        cells = [cell.strip().lstrip("\ufeff").upper() for cell in record]
        return "EN_YEAR" in cells and "TOTAL" in cells

    header_index = next((i for i, row in enumerate(records) if is_header(row)), None)

    if header_index is None:
        header_index = next(
            (i for i, row in enumerate(records) if any(cell.strip() for cell in row)),
            None,
        )

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = [cell.lstrip("\ufeff") for cell in records[header_index]]
    width = len(columns)
    rows = []

    for record in records[header_index + 1:]:
        if not record or not any(cell for cell in record):
            continue
        row = list(record)
        if len(row) < width:
            row.extend([""] * (width - len(row)))
        elif len(row) > width and width:
            row = row[:width - 1] + ["\t".join(row[width - 1:])]
        rows.append(row)

    return {"columns": columns, "rows": rows}
